<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import OperationsRecovery from './OperationsRecovery.vue';import SendMinutesDialog from '../mail/SendMinutesDialog.vue';
import GovernanceVoices from './GovernanceVoices.vue';import GovernanceCorpus from './GovernanceCorpus.vue';import GovernanceConfiguration from './GovernanceConfiguration.vue';import GovernanceEvaluation from './GovernanceEvaluation.vue';import GovernanceDatasets from './GovernanceDatasets.vue';import GovernanceReport from './GovernanceReport.vue';import type {Capability} from './workbench-types';import './governance.css';
const app=useApplication(),ops=app.operationsCommands,route=useRoute(),capability=ref<Capability|null>(null),error=ref(''),loading=ref(false),mail=ref<InstanceType<typeof SendMinutesDialog>>();let epoch=0;
const actor=()=>app.session.current.value?.actor.enterpriseId??null,tabs=[['voiceprints','声纹管理','user'],['corpus','语料管理','kb'],['evaluation','质量评测','layers'],['configuration','系统配置','shield']] as const;
const section=computed(()=>route.path.split('/')[2]??'voiceprints');
const view=computed(()=>section.value==='voiceprints'?GovernanceVoices:section.value==='corpus'?GovernanceCorpus:section.value==='configuration'?GovernanceConfiguration:route.path.endsWith('/datasets')?GovernanceDatasets:route.params.id?GovernanceReport:GovernanceEvaluation);
async function load(){const turn=++epoch;capability.value=null;error.value='';if(!actor()||!ops.available.value)return;loading.value=true;try{const data=await ops.read<Capability>('/api/v1/operations/capabilities');if(turn===epoch)capability.value=data;}catch(cause){if(turn===epoch)error.value=cause instanceof Error?cause.message:'治理权限暂无法核实。';}finally{if(turn===epoch)loading.value=false;}}
async function recheck(){error.value='';try{await ops.recheck(()=>app.session.refresh());await load();}catch(cause){error.value=cause instanceof Error?cause.message:'请重新登录。';}}
watch([actor,()=>ops.available.value],()=>void load(),{immediate:true,flush:'sync'});
watch([()=>route.query.meetingId,()=>mail.value,actor],([id,modal,who])=>{if(typeof id==='string'&&modal&&who)void modal.open(id);},{flush:'post',immediate:true});
onUnmounted(()=>epoch++);
</script>
<template><main class="content governance-page"><header class="governance-heading"><div><span class="gov-eyebrow">OPERATIONS & QUALITY</span><h1>运营治理<span>持续改善会议质量</span></h1><p>从用户反馈到质量验证，让每一次配置调整都有依据、可追溯。</p></div><RouterLink class="btn" to="/feedback"><Icon name="message"/>我的反馈</RouterLink></header><OperationsRecovery/><p v-if="error||app.operationsScopeError.value" class="banner error" role="alert">{{error||app.operationsScopeError.value}}</p>
<div v-if="!actor()" class="gov-empty card"><h2>请登录企业账号</h2><RouterLink class="btn primary" to="/login">企业登录</RouterLink></div><div v-else-if="!ops.available.value" class="gov-empty card"><h2>当前身份需要重新核实</h2><button class="btn primary" @click="recheck">重新检查登录</button></div><div v-else-if="loading" class="gov-loading card" role="status">正在核实治理权限…</div><div v-else-if="capability&&!capability.reviewer" class="gov-empty card"><Icon name="shield" :size="36"/><h2>运营治理由平台管理员维护</h2><p>你可以管理本人授权，或查看已提交反馈的处理进展。</p><div class="module-actions"><RouterLink class="btn primary" to="/my/voiceprints">我的声纹</RouterLink><RouterLink class="btn" to="/feedback">我的反馈</RouterLink></div></div><template v-else-if="capability?.reviewer"><nav class="governance-nav" aria-label="运营治理模块"><RouterLink v-for="[key,label,icon] in tabs" :key="key" :to="'/operations/'+key" :class="{active:section===key}" :aria-current="section===key?'page':undefined"><Icon :name="icon" :size="18"/>{{label}}</RouterLink></nav><component :is="view" v-bind="view===GovernanceReport?{id:String(route.params.id)}:{}" :key="actor()+route.path"/></template><button v-else-if="error" class="btn" @click="load">重试权限读取</button><SendMinutesDialog ref="mail"/></main></template>
